        x2, y2 = other_point.x, other_point.y
        return ((x1 - x2) ** 2 + (y1 - y2) ** 2) ** 0.5

def fibonacci_seq(n):
    seq = [0, 1]
    for i in range(2, n):
        seq.append(seq[i-1] + seq[i-2])
    return seq

